def page(path,title,description,body,structured=None):
    jsonld=''
    csp="default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; manifest-src 'self'; base-uri 'none'; form-action 'none'; upgrade-insecure-requests"
    if structured:
        encoded=json.dumps(structured,separators=(',',':'),ensure_ascii=False).replace('<','\\u003c')
        digest=base64.b64encode(hashlib.sha256(encoded.encode()).digest()).decode()
        csp=csp.replace("script-src 'self'",f"script-src 'self' 'sha256-{digest}'")
        jsonld=f'<script type="application/ld+json">{encoded}</script>'
    canonical=ORIGIN+path
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="{e(csp,quote=True)}"><title>{e(title)}</title><meta name="description" content="{e(description,quote=True)}"><meta name="referrer" content="no-referrer"><meta name="theme-color" content="#152a25"><meta name="color-scheme" content="light dark"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/social-card.png"><meta property="og:image:alt" content="Awais Ali — Cybersecurity, software development, and applied AI"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script>{jsonld}</head><body>{header()}<main id="main">{body}</main>{footer()}</body></html>'''
    target=DIST/(path.strip('/')+'/index.html' if path!='/' else 'index.html')
    target.parent.mkdir(parents=True,exist_ok=True);target.write_text(prefix_local_urls(html), encoding='utf-8')

def cover(p):
    v=p['visual']
    if v=='monitor':art='''<div class="terminal"><div class="terminal-head"><i class="terminal-dot"></i><i class="terminal-dot"></i><i class="terminal-dot"></i><span>awais@security-lab</span></div><div class="terminal-body"><div class="line-muted">$ monitor --endpoint ubuntu</div><strong>Every event tells a story.</strong><div class="terminal-row"><span>file_integrity</span><b>change detected</b></div><div class="terminal-row"><span>ssh_authentication</span><b>alert triggered</b></div><div class="line-muted">→ investigate · document · respond</div></div></div>'''
    elif v=='encryption':art=f'<div class="encryption-art"><div class="file-icon">file.txt</div><div class="cipher">a9 f2 e8<br>7b 0c d4<br>e3 8a 1f</div><div class="lock-orb">{icon("lock")}</div></div>'
    elif v=='mesh':art='''<div class="mesh-art"><svg viewBox="0 0 360 220" fill="none"><g stroke="#dafa92" stroke-width="1"><circle cx="180" cy="110" r="88" opacity=".12"/><circle cx="180" cy="110" r="61" opacity=".18"/><path d="m65 150 115-40 113 45M180 110l63-76M65 150l-14-88 129 48" stroke-dasharray="4 5" opacity=".65"/><circle cx="180" cy="110" r="32" fill="#dafa92"/><rect x="47" y="42" width="22" height="39" rx="5" fill="#294838"/><rect x="54" y="132" width="22" height="39" rx="5" fill="#294838"/><rect x="282" y="136" width="22" height="39" rx="5" fill="#294838"/><rect x="232" y="17" width="22" height="39" rx="5" fill="#294838"/></g><g font-family="monospace" text-anchor="middle"><text x="180" y="115" fill="#172e27" font-size="15">SOS</text><text x="180" y="209" fill="#c5d5b2" font-size="9" letter-spacing="2">NEARBY. CONNECTED. OFFLINE.</text></g></svg></div>'''
    elif v=='vision':art='''<div class="vision-art"><div class="scan"><svg viewBox="0 0 100 120" fill="none"><path d="M50 12C13 9 8 42 15 70s16 38 35 39c24 0 41-30 38-55S75 9 50 12Z" stroke="#b8bac8" stroke-width="2"/><path d="M49 18v85M25 40q30 30 0 40M74 37q-28 31 0 45M29 28q17 8 10 28M68 26Q50 46 67 61M32 84q15-22 7 11M62 75q-9 19 6 24" stroke="#7d8296"/><circle cx="65" cy="48" r="13" fill="#cfe29b" opacity=".4"/><circle cx="65" cy="48" r="6" fill="#dafa92"/></svg></div><div class="scan-grid">'''+('<span></span>'*16)+'''</div></div>'''
    else:art=f'<div class="simple-art">{icon({"audit":"shield","cloud":"cloud","response":"response","music":"music","code":"code"}.get(v,"code"))}</div>'
    return f'<div class="project-cover cover-{v}" aria-hidden="true"><div class="cover-topline"><span>AA / {e(p["short"])}</span><span>{e(p["year"])}</span></div>{art}<span class="cover-foot">Concept illustration · {e(p["category"])}</span></div>'
