page('/404/','Page not found — Awais Ali','The requested portfolio page could not be found.','<section class="container notfound"><div class="eyebrow label">A small detour</div><h1>404</h1><h2>This page is off the map.</h2><p>The link may have changed. You can still explore the work or return to the homepage.</p>'+button('/','Back to home')+'</section>')
shutil.copyfile(DIST/'404/index.html',DIST/'404.html')
(DIST/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="32" fill="#152a25"/><text x="11" y="43" fill="#dafa92" font-family="Georgia,serif" font-style="italic" font-size="39">aa.</text></svg>', encoding='utf-8')
(DIST/'robots.txt').write_text(f'User-agent: *\nAllow: {BASE_PATH}/\nDisallow: {BASE_PATH}/404/\nSitemap: {ORIGIN}/sitemap.xml\n', encoding='utf-8')
urls=['/','/projects/','/credentials/']+['/projects/'+p['slug']+'/' for p in PROJECTS]+['/'+k+'/' for k in legal_pages]
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{u}</loc><lastmod>2026-10-28</lastmod></url>' for u in urls)+'</urlset>', encoding='utf-8')
(DIST/'.well-known').mkdir(exist_ok=True)
(DIST/'.well-known/security.txt').write_text(f'Contact: mailto:{EMAIL}\nExpires: 2027-10-27T00:00:00Z\nPreferred-Languages: en, ur\nCanonical: {ORIGIN}/.well-known/security.txt\nPolicy: {ORIGIN}/security/\n', encoding='utf-8')
basecsp="default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; object-src 'none'; frame-src 'none'; media-src 'none'; worker-src 'none'; manifest-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; upgrade-insecure-requests"
# JSON-LD is inert metadata, but match its allowed hash in the response policy as well.
home=(DIST/'index.html').read_text(encoding='utf-8'); data=home.split('<script type="application/ld+json">')[1].split('</script>')[0]
digest=base64.b64encode(hashlib.sha256(data.encode()).digest()).decode()
basecsp=basecsp.replace("script-src 'self'",f"script-src 'self' 'sha256-{digest}'")
(DIST/'_headers').write_text('/*\n  Content-Security-Policy: '+basecsp+'\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: no-referrer\n  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=(), browsing-topics=()\n  Strict-Transport-Security: max-age=31536000\n  Cross-Origin-Opener-Policy: same-origin\n  Cross-Origin-Resource-Policy: same-origin\n  X-DNS-Prefetch-Control: off\n\n'+BASE_PATH+'/downloads/*\n  Content-Disposition: attachment\n', encoding='utf-8')
print('Built',len(urls),'content routes, a 404 page, sitemap, security.txt, and header configuration.')

